use std::alloc::{GlobalAlloc, Layout, System};
use std::fmt::Write;
use std::sync::atomic::{AtomicUsize, Ordering};

// A tally counter on the heap's front desk: every request for heap memory
// (new or bigger) adds 1, then the normal allocator does the real work.
// Writing your own allocator needs `unsafe`; you will rarely do this. It's here to measure.
struct Tally;
static ALLOCATIONS: AtomicUsize = AtomicUsize::new(0);

unsafe impl GlobalAlloc for Tally {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        unsafe { System.dealloc(ptr, layout) }
    }
}

#[global_allocator]
static TALLY: Tally = Tally;

// Runs `job` and returns how many heap allocations it made.
fn count<T>(job: impl FnOnce() -> T) -> usize {
    let before = ALLOCATIONS.load(Ordering::Relaxed);
    let result = job();
    let after = ALLOCATIONS.load(Ordering::Relaxed);
    drop(result);
    after - before
}

fn longest_cloned(titles: Vec<String>) -> String {
    let mut best = String::new();
    for t in titles.clone() {
        if t.len() > best.len() {
            best = t.clone();
        }
    }
    best
}

fn longest_borrowed(titles: &[String]) -> &str {
    let mut best = "";
    for t in titles {
        if t.len() > best.len() {
            best = t;
        }
    }
    best
}

fn vowels_owned(word: String) -> usize {
    word.chars().filter(|c| "aeiou".contains(*c)).count()
}

fn vowels_borrowed(word: &str) -> usize {
    word.chars().filter(|c| "aeiou".contains(*c)).count()
}

fn main() {
    let shelf = vec![String::from("Emma"), String::from("Middlemarch"), String::from("Dune")];
    let mut results = Vec::with_capacity(8);

    results.push(("push 1000 numbers, no capacity", count(|| {
        let mut v = Vec::new();
        for i in 0..1000 {
            v.push(i);
        }
        v
    })));
    results.push(("push 1000 numbers, with_capacity", count(|| {
        let mut v = Vec::with_capacity(1000);
        for i in 0..1000 {
            v.push(i);
        }
        v
    })));
    results.push(("longest title, clone-heavy", count(|| longest_cloned(shelf.clone()))));
    results.push(("longest title, borrowing", count(|| longest_borrowed(&shelf).len())));
    results.push(("100 labels, a new String each", count(|| {
        let mut letters = 0;
        for i in 0..100 {
            let label = format!("shelf {i}");
            letters += label.len();
        }
        letters
    })));
    results.push(("100 labels, one reused buffer", count(|| {
        let mut letters = 0;
        let mut label = String::new();
        for i in 0..100 {
            label.clear();
            write!(label, "shelf {i}").unwrap();
            letters += label.len();
        }
        letters
    })));
    results.push(("100 vowel counts, String parameter", count(|| {
        let mut total = 0;
        for _ in 0..100 {
            total += vowels_owned("Middlemarch".to_string());
        }
        total
    })));
    results.push(("100 vowel counts, &str parameter", count(|| {
        let mut total = 0;
        for _ in 0..100 {
            total += vowels_borrowed("Middlemarch");
        }
        total
    })));

    for (what, n) in results {
        println!("{what}: {n} allocations");
    }
}

