#[derive(Default)]
struct Report {
    title: String,
    max_rows: usize,
    sorted: bool,
}

impl Report {
    fn titled(title: &str) -> Report {
        Report { title: title.to_string(), max_rows: 3, ..Default::default() }
    }
    fn sorted(mut self) -> Report {
        self.sorted = true;
        self
    }
    fn render(&self, scores: &[u32]) -> String {
        let mut rows = scores.to_vec();
        if self.sorted {
            rows.sort_unstable_by(|a, b| b.cmp(a));
        }
        let shown: Vec<String> = rows.iter().take(self.max_rows).map(|s| s.to_string()).collect();
        format!("{}: [{}]", self.title, shown.join(", "))
    }
}

fn main() {
    let scores = [40, 95, 12, 77, 60];
    println!("{}", Report::titled("as read").render(&scores));
    println!("{}", Report::titled("top").sorted().render(&scores));
    println!("{}", Report { max_rows: 5, ..Report::titled("all") }.render(&scores));
}

