use std::fmt;

#[derive(Debug)]
enum Size {
    Small,
    Medium,
    Large,
}

/// A cup of tea from the library café.
struct Tea {
    flavor: String,
    size: Size,
    sugar: u8,
    to_go: bool,
}

/// Collects your choices, then [`TeaBuilder::build`] makes the [`Tea`].
///
/// # Examples
///
/// ```
/// let tea = Tea::order("mint").sugar(1).build();
/// ```
struct TeaBuilder {
    flavor: String,
    size: Size,
    sugar: u8,
    to_go: bool,
}

impl Tea {
    /// Starts an order. Anything you don't choose stays at its default:
    /// medium, no sugar, for here.
    fn order(flavor: &str) -> TeaBuilder {
        TeaBuilder { flavor: flavor.to_string(), size: Size::Medium, sugar: 0, to_go: false }
    }
}

impl TeaBuilder {
    fn size(mut self, size: Size) -> TeaBuilder {
        self.size = size;
        self
    }
    fn sugar(mut self, spoons: u8) -> TeaBuilder {
        self.sugar = spoons;
        self
    }
    fn to_go(mut self) -> TeaBuilder {
        self.to_go = true;
        self
    }
    fn build(self) -> Tea {
        Tea { flavor: self.flavor, size: self.size, sugar: self.sugar, to_go: self.to_go }
    }
}

impl fmt::Display for Tea {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let place = if self.to_go { "to go" } else { "for here" };
        write!(f, "{:?} {} tea, sugar {}, {}", self.size, self.flavor, self.sugar, place)
    }
}

fn main() {
    let plain = Tea::order("mint").build();
    let big = Tea::order("chai").size(Size::Large).sugar(2).build();
    let quick = Tea::order("lemon").to_go().size(Size::Small).build();
    println!("{plain}");
    println!("{big}");
    println!("{quick}");
}

