fn main() {
    let pages: Vec<u32> = vec![120, 80, 300, 45];

    // an index loop: works, but you manage i yourself
    let mut long_total = 0;
    for i in 0..pages.len() {
        if pages[i] > 100 {
            long_total += pages[i];
        }
    }

