fn main() {
    println!("u8          {:>3} byte", size_of::<u8>());
    println!("u64         {:>3} bytes", size_of::<u64>());
    println!("[u64; 50]   {:>3} bytes", size_of::<[u64; 50]>());
    println!("&str        {:>3} bytes (pointer + length)", size_of::<&str>());
    println!("String      {:>3} bytes (pointer + length + capacity)", size_of::<String>());
    println!("Vec<u64>    {:>3} bytes, whatever its length", size_of::<Vec<u64>>());
